    "solutionCode": "'use strict';\n\nclass CircularDeque {\n  constructor(initialCapacity = 8) {\n    let cap = 1;\n    while (cap < Math.max(4, initialCapacity)) cap <<= 1;\n    this._capacity = cap;\n    this._mask = cap - 1;\n    this._buf = new Array(cap).fill(undefined);\n    this._head = 0;\n    this._size = 0;\n    this._resizes = 0;\n    this._copiedElements = 0;\n  }\n\n  get size() { return this._size; }\n  get capacity() { return this._capacity; }\n  get isEmpty() { return this._size === 0; }\n\n  _physIndex(logicalIdx) {\n    return (this._head + logicalIdx) & this._mask;\n  }\n\n  _resize(newCap) {\n    const next = new Array(newCap).fill(undefined);\n    for (let i = 0; i < this._size; i++) {\n      next[i] = this._buf[(this._head + i) & this._mask];\n    }\n    this._copiedElements += this._size;\n    this._resizes++;\n    this._buf = next;\n    this._capacity = newCap;\n    this._mask = newCap - 1;\n    this._head = 0;\n  }\n\n  pushBack(value) {\n    if (this._size === this._capacity) {\n      this._resize(this._capacity * 2);\n    }\n    const tail = (this._head + this._size) & this._mask;\n    this._buf[tail] = value;\n    this._size++;\n    return this._size;\n  }\n\n  pushFront(value) {\n    if (this._size === this._capacity) {\n      this._resize(this._capacity * 2);\n    }\n    this._head = (this._head - 1) & this._mask;\n    this._buf[this._head] = value;\n    this._size++;\n    return this._size;\n  }\n\n  popFront() {\n    if (this._size === 0) return undefined;\n    const val = this._buf[this._head];\n    this._buf[this._head] = undefined;\n    this._head = (this._head + 1) & this._mask;\n    this._size--;\n    if (this._capacity > 8 && this._size <= (this._capacity >> 2)) {\n      this._resize(this._capacity >> 1);\n    }\n    return val;\n  }\n\n  popBack() {\n    if (this._size === 0) return undefined;\n    const tail = (this._head + this._size - 1) & this._mask;\n    const val = this._buf[tail];\n    this._buf[tail] = undefined;\n    this._size--;\n    if (this._capacity > 8 && this._size <= (this._capacity >> 2)) {\n      this._resize(this._capacity >> 1);\n    }\n    return val;\n  }\n\n  get(index) {\n    if (index < 0 || index >= this._size) throw new RangeError('Index out of bounds');\n    return this._buf[this._physIndex(index)];\n  }\n\n  set(index, value) {\n    if (index < 0 || index >= this._size) throw new RangeError('Index out of bounds');\n    this._buf[this._physIndex(index)] = value;\n  }\n\n  peekFront() { return this._size === 0 ? undefined : this._buf[this._head]; }\n  peekBack() { return this._size === 0 ? undefined : this._buf[this._physIndex(this._size - 1)]; }\n\n  toArray() {\n    const out = new Array(this._size);\n    for (let i = 0; i < this._size; i++) out[i] = this._buf[this._physIndex(i)];\n    return out;\n  }\n\n  potential() {\n    return Math.max(0, 2 * this._size - this._capacity / 2);\n  }\n}\n\nmodule.exports = { CircularDeque };\n",
