    "starterCode": "'use strict';\n\nclass DLNode {\n  constructor(key = null, value = null) {\n    this.key = key;\n    this.value = value;\n    this.freq = 1;\n    this.prev = null;\n    this.next = null;\n  }\n}\n\nclass DoublyLinkedList {\n  constructor() {\n    this.head = new DLNode();\n    this.tail = new DLNode();\n    this.head.next = this.tail;\n    this.tail.prev = this.head;\n    this.size = 0;\n  }\n\n  addFront(node) {\n    // TODO (Step 1): Insert node right after sentinel head\n  }\n\n  remove(node) {\n    // TODO (Step 1): Unlink node from its neighbors and decrement size\n    return node;\n  }\n\n  popBack() {\n    if (this.size === 0) return null;\n    return this.remove(this.tail.prev);\n  }\n}\n\nclass LRUCache {\n  constructor(capacity) {\n    if (capacity < 1) throw new RangeError('Capacity must be >= 1');\n    this.capacity = capacity;\n    this.map = new Map();\n    this.list = new DoublyLinkedList();\n  }\n\n  get(key) {\n    // TODO (Step 2): Return -1 if missing; otherwise move node to front and return value\n    return -1;\n  }\n\n  put(key, value) {\n    // TODO (Step 2): Update existing or insert new node at front; evict LRU tail if over capacity\n  }\n}\n\nclass LFUCache {\n  constructor(capacity) {\n    if (capacity < 1) throw new RangeError('Capacity must be >= 1');\n    this.capacity = capacity;\n    this.minFreq = 0;\n    this.nodes = new Map();\n    this.buckets = new Map();\n  }\n\n  _getBucket(freq) {\n    let b = this.buckets.get(freq);\n    if (!b) { b = new DoublyLinkedList(); this.buckets.set(freq, b); }\n    return b;\n  }\n\n  _promote(node) {\n    // TODO (Step 3): Remove node from bucket[node.freq], advance minFreq if bucket became empty,\n    // increment node.freq, and addFront to bucket[node.freq]\n  }\n\n  get(key) {\n    const node = this.nodes.get(key);\n    if (!node) return -1;\n    this._promote(node);\n    return node.value;\n  }\n\n  put(key, value) {\n    // TODO (Step 4): Update + promote if present; otherwise evict from buckets.get(minFreq).popBack()\n    // when full, insert new node with freq = 1, and set minFreq = 1.\n  }\n}\n\nmodule.exports = { DLNode, DoublyLinkedList, LRUCache, LFUCache };\n",
    "solutionCode": "'use strict';\n\nclass DLNode {\n  constructor(key = null, value = null) {\n    this.key = key;\n    this.value = value;\n    this.freq = 1;\n    this.prev = null;\n    this.next = null;\n  }\n}\n\nclass DoublyLinkedList {\n  constructor() {\n    this.head = new DLNode();\n    this.tail = new DLNode();\n    this.head.next = this.tail;\n    this.tail.prev = this.head;\n    this.size = 0;\n  }\n\n  addFront(node) {\n    node.next = this.head.next;\n    node.prev = this.head;\n    this.head.next.prev = node;\n    this.head.next = node;\n    this.size++;\n  }\n\n  remove(node) {\n    node.prev.next = node.next;\n    node.next.prev = node.prev;\n    node.prev = null;\n    node.next = null;\n    this.size--;\n    return node;\n  }\n\n  popBack() {\n    if (this.size === 0) return null;\n    return this.remove(this.tail.prev);\n  }\n}\n\nclass LRUCache {\n  constructor(capacity) {\n    if (capacity < 1) throw new RangeError('Capacity must be >= 1');\n    this.capacity = capacity;\n    this.map = new Map();\n    this.list = new DoublyLinkedList();\n  }\n\n  get(key) {\n    const node = this.map.get(key);\n    if (!node) return -1;\n    this.list.remove(node);\n    this.list.addFront(node);\n    return node.value;\n  }\n\n  put(key, value) {\n    const existing = this.map.get(key);\n    if (existing) {\n      existing.value = value;\n      this.list.remove(existing);\n      this.list.addFront(existing);\n      return;\n    }\n    if (this.map.size === this.capacity) {\n      const evicted = this.list.popBack();\n      if (evicted) this.map.delete(evicted.key);\n    }\n    const node = new DLNode(key, value);\n    this.list.addFront(node);\n    this.map.set(key, node);\n  }\n}\n\nclass LFUCache {\n  constructor(capacity) {\n    if (capacity < 1) throw new RangeError('Capacity must be >= 1');\n    this.capacity = capacity;\n    this.minFreq = 0;\n    this.nodes = new Map();\n    this.buckets = new Map();\n  }\n\n  _getBucket(freq) {\n    let b = this.buckets.get(freq);\n    if (!b) { b = new DoublyLinkedList(); this.buckets.set(freq, b); }\n    return b;\n  }\n\n  _promote(node) {\n    const oldFreq = node.freq;\n    const oldBucket = this._getBucket(oldFreq);\n    oldBucket.remove(node);\n    if (oldBucket.size === 0) {\n      this.buckets.delete(oldFreq);\n      if (this.minFreq === oldFreq) this.minFreq = oldFreq + 1;\n    }\n    node.freq = oldFreq + 1;\n    this._getBucket(node.freq).addFront(node);\n  }\n\n  get(key) {\n    const node = this.nodes.get(key);\n    if (!node) return -1;\n    this._promote(node);\n    return node.value;\n  }\n\n  put(key, value) {\n    const existing = this.nodes.get(key);\n    if (existing) {\n      existing.value = value;\n      this._promote(existing);\n      return;\n    }\n    if (this.nodes.size === this.capacity) {\n      const minBucket = this.buckets.get(this.minFreq);\n      const evicted = minBucket.popBack();\n      if (minBucket.size === 0) this.buckets.delete(this.minFreq);\n      this.nodes.delete(evicted.key);\n    }\n    const node = new DLNode(key, value);\n    node.freq = 1;\n    this.minFreq = 1;\n    this._getBucket(1).addFront(node);\n    this.nodes.set(key, node);\n  }\n}\n\nmodule.exports = { DLNode, DoublyLinkedList, LRUCache, LFUCache };\n",
    "testHarness": "function runTests() {\n  const assert = require('node:assert/strict');\n\n  // Test DoublyLinkedList\n  const dll = new DoublyLinkedList();\n  const n1 = new DLNode('a', 1), n2 = new DLNode('b', 2);\n  dll.addFront(n1);\n  dll.addFront(n2);\n  assert.equal(dll.size, 2);\n  assert.equal(dll.popBack().key, 'a');\n  assert.equal(dll.popBack().key, 'b');\n  assert.equal(dll.popBack(), null);\n\n  // Test LRUCache\n  const lru = new LRUCache(2);\n  lru.put(1, 10);\n  lru.put(2, 20);\n  assert.equal(lru.get(1), 10); // 2 is now LRU\n  lru.put(3, 30); // evicts 2\n  assert.equal(lru.get(2), -1);\n  assert.equal(lru.get(3), 30);\n\n  // Test LFUCache with LRU tie-breaking\n  const lfu = new LFUCache(2);\n  lfu.put(1, 1);\n  lfu.put(2, 2);\n  assert.equal(lfu.get(1), 1);   // freq(1)=2, freq(2)=1, minFreq=1\n  lfu.put(3, 3);                 // evicts key 2 (freq 1)\n  assert.equal(lfu.get(2), -1);\n  assert.equal(lfu.get(3), 3);   // freq(3)=2, minFreq=2\n  lfu.put(4, 4);                 // tie at freq=2: key 1 is older than key 3 -> evicts key 1\n  assert.equal(lfu.get(1), -1);\n  assert.equal(lfu.get(3), 3);\n  assert.equal(lfu.get(4), 4);\n  return true;\n}\nrunTests();\n",
