      "index.js": "'use strict';\n\nfunction fnv1a32(key) {\n  const str = String(key);\n  let h = 0x811c9dc5;\n  for (let i = 0; i < str.length; i++) {\n    h ^= str.charCodeAt(i);\n    h = Math.imul(h, 0x01000193);\n  }\n  return h >>> 0;\n}\n\nclass RobinHoodHashMap {\n  constructor(initialCapacity = 16, maxLoadFactor = 0.75) {\n    let cap = 1;\n    while (cap < Math.max(8, initialCapacity)) cap <<= 1;\n    this._capacity = cap;\n    this._mask = cap - 1;\n    this._maxLoad = maxLoadFactor;\n    this._size = 0;\n    this._slots = new Array(cap).fill(null);\n  }\n\n  get size() { return this._size; }\n  get capacity() { return this._capacity; }\n\n  _idealIndex(key) {\n    return fnv1a32(key) & this._mask;\n  }\n\n  _psl(slotIdx, idealIdx) {\n    // TODO (Step 1): Compute Probe Sequence Length (distance from idealIdx to slotIdx on ring)\n    return 0;\n  }\n\n  set(key, value) {\n    // TODO (Step 2): Resize if load factor >= _maxLoad; insert with Robin Hood displacement\n    // whenever incoming psl > occupant psl.\n  }\n\n  get(key) {\n    // TODO (Step 3): Probe from ideal index; early-exit if slot is empty OR slot.psl < current psl\n    return undefined;\n  }\n\n  has(key) {\n    return this.get(key) !== undefined;\n  }\n\n  delete(key) {\n    // TODO (Step 4): Find key, remove it, and backward-shift subsequent slots with psl > 0\n    return false;\n  }\n\n  _resize(newCap) {\n    const old = this._slots;\n    this._capacity = newCap;\n    this._mask = newCap - 1;\n    this._size = 0;\n    this._slots = new Array(newCap).fill(null);\n    for (const entry of old) {\n      if (entry !== null) this.set(entry.key, entry.value);\n    }\n  }\n\n  maxPSL() {\n    let max = 0;\n    for (const s of this._slots) if (s && s.psl > max) max = s.psl;\n    return max;\n  }\n}\n\nmodule.exports = { RobinHoodHashMap, fnv1a32 };\n",
      "test.js": "'use strict';\n\nconst exported = require('./index.js');\nObject.assign(globalThis, exported);\n\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const map = new RobinHoodHashMap(8, 0.75);\n\n  // Insert colliding & non-colliding keys\n  for (let i = 0; i < 200; i++) {\n    map.set('key:' + i, i * 10);\n  }\n  assert.equal(map.size, 200);\n  for (let i = 0; i < 200; i++) {\n    assert.equal(map.get('key:' + i), i * 10);\n  }\n  assert.equal(map.get('missing'), undefined);\n\n  // Update existing keys\n  map.set('key:50', 9999);\n  assert.equal(map.get('key:50'), 9999);\n  assert.equal(map.size, 200);\n\n  // Backward-shift deletion preserves PSL invariant & lookup correctness\n  for (let i = 0; i < 100; i += 2) {\n    assert.equal(map.delete('key:' + i), true);\n    assert.equal(map.delete('key:' + i), false);\n  }\n  assert.equal(map.size, 150);\n\n  for (let i = 0; i < 200; i++) {\n    if (i < 100 && i % 2 === 0) assert.equal(map.has('key:' + i), false);\n    else assert.equal(map.get('key:' + i), i === 50 ? 9999 : i * 10);\n  }\n\n  // Verify PSL invariant on every occupied slot\n  for (let idx = 0; idx < map._capacity; idx++) {\n    const s = map._slots[idx];\n    if (s) assert.equal(s.psl, map._psl(idx, map._idealIndex(s.key)));\n  }\n  return true;\n}\nrunTests();\n\n\n",
