      "index.js": "'use strict';\n\nconst RED = true;\nconst BLACK = false;\n\nclass LLRBNode {\n  constructor(key, value, color = RED) {\n    this.key = key;\n    this.value = value;\n    this.color = color;\n    this.left = null;\n    this.right = null;\n    this.size = 1;\n  }\n}\n\nclass OrderStatisticLLRB {\n  constructor(compareFn = (a, b) => (a < b ? -1 : a > b ? 1 : 0)) {\n    this._root = null;\n    this._cmp = compareFn;\n  }\n\n  get size() { return this._nodeSize(this._root); }\n\n  _isRed(h) { return h !== null && h.color === RED; }\n  _nodeSize(h) { return h === null ? 0 : h.size; }\n  _update(h) {\n    if (h) h.size = 1 + this._nodeSize(h.left) + this._nodeSize(h.right);\n    return h;\n  }\n\n  _rotateLeft(h) {\n    // TODO (Step 1): Rotate right-leaning red link to left; update colors and subtree sizes\n    return h;\n  }\n\n  _rotateRight(h) {\n    // TODO (Step 1): Rotate left-leaning link to right; update colors and subtree sizes\n    return h;\n  }\n\n  _flipColors(h) {\n    // TODO (Step 1): Toggle color of h and both children (split/merge 4-node)\n  }\n\n  _fixUp(h) {\n    // TODO (Step 2): Enforce LLRB invariants:\n    // 1. Right-leaning red link -> rotateLeft\n    // 2. Two consecutive left red links -> rotateRight\n    // 3. Both children red -> flipColors\n    return this._update(h);\n  }\n\n  put(key, value = key) {\n    this._root = this._put(this._root, key, value);\n    this._root.color = BLACK;\n  }\n\n  _put(h, key, value) {\n    // TODO (Step 2): Standard BST insert at leaf (RED), then _fixUp(h) on the way up\n    return h;\n  }\n\n  get(key) {\n    let curr = this._root;\n    while (curr !== null) {\n      const c = this._cmp(key, curr.key);\n      if (c === 0) return curr.value;\n      curr = c < 0 ? curr.left : curr.right;\n    }\n    return undefined;\n  }\n\n  has(key) { return this.get(key) !== undefined; }\n\n  rank(key) {\n    // TODO (Step 3): Return number of keys strictly less than `key` in O(log n)\n    return 0;\n  }\n\n  select(k) {\n    // TODO (Step 3): Return the k-th smallest key (0-indexed) in O(log n)\n    return undefined;\n  }\n\n  delete(key) {\n    // TODO (Step 4): Remove key while preserving LLRB balance and subtree sizes\n    return false;\n  }\n}\n\nmodule.exports = { OrderStatisticLLRB, RED, BLACK };\n",
