      "index.js": "'use strict';\n\nclass ImplicitTreapNode {\n  constructor(value, priority) {\n    this.value = value;\n    this.priority = priority;\n    this.size = 1;\n    this.sum = typeof value === 'number' ? value : 0;\n    this.rev = false;\n    this.left = null;\n    this.right = null;\n  }\n}\n\nclass ImplicitTreapRope {\n  constructor(items = [], seed = 0x9E3779B9) {\n    this._rngState = seed >>> 0 || 1;\n    this._root = null;\n    for (const item of items) this.pushBack(item);\n  }\n\n  _nextPriority() {\n    let x = this._rngState;\n    x ^= x << 13;\n    x ^= x >>> 17;\n    x ^= x << 5;\n    this._rngState = x >>> 0;\n    return this._rngState;\n  }\n\n  get size() { return this._sz(this._root); }\n  _sz(t) { return t ? t.size : 0; }\n  _sm(t) { return t ? t.sum : 0; }\n\n  _push(t) {\n    if (!t || !t.rev) return;\n    const tmp = t.left;\n    t.left = t.right;\n    t.right = tmp;\n    if (t.left) t.left.rev = !t.left.rev;\n    if (t.right) t.right.rev = !t.right.rev;\n    t.rev = false;\n  }\n\n  _pull(t) {\n    if (!t) return null;\n    t.size = 1 + this._sz(t.left) + this._sz(t.right);\n    t.sum = (typeof t.value === 'number' ? t.value : 0) + this._sm(t.left) + this._sm(t.right);\n    return t;\n  }\n\n  split(t, k) {\n    if (!t) return [null, null];\n    this._push(t);\n    const leftSize = this._sz(t.left);\n    if (k <= leftSize) {\n      const [ll, lr] = this.split(t.left, k);\n      t.left = lr;\n      this._pull(t);\n      return [ll, t];\n    } else {\n      const [rl, rr] = this.split(t.right, k - leftSize - 1);\n      t.right = rl;\n      this._pull(t);\n      return [t, rr];\n    }\n  }\n\n  merge(left, right) {\n    if (!left || !right) return left || right;\n    this._push(left);\n    this._push(right);\n    if (left.priority >= right.priority) {\n      left.right = this.merge(left.right, right);\n      return this._pull(left);\n    } else {\n      right.left = this.merge(left, right.left);\n      return this._pull(right);\n    }\n  }\n\n  insertAt(index, value) {\n    const [l, r] = this.split(this._root, index);\n    const node = new ImplicitTreapNode(value, this._nextPriority());\n    this._root = this.merge(this.merge(l, node), r);\n  }\n\n  pushBack(value) { this.insertAt(this.size, value); }\n\n  deleteAt(index) {\n    if (index < 0 || index >= this.size) return undefined;\n    const [l, mr] = this.split(this._root, index);\n    const [m, r] = this.split(mr, 1);\n    this._root = this.merge(l, r);\n    return m ? m.value : undefined;\n  }\n\n  get(index) {\n    if (index < 0 || index >= this.size) return undefined;\n    let curr = this._root;\n    let k = index;\n    while (curr) {\n      this._push(curr);\n      const leftSize = this._sz(curr.left);\n      if (k < leftSize) curr = curr.left;\n      else if (k > leftSize) {\n        k -= leftSize + 1;\n        curr = curr.right;\n      } else return curr.value;\n    }\n    return undefined;\n  }\n\n  reverseRange(l, r) {\n    if (l < 0 || r >= this.size || l >= r) return;\n    const [t1, t23] = this.split(this._root, l);\n    const [t2, t3] = this.split(t23, r - l + 1);\n    if (t2) t2.rev = !t2.rev;\n    this._root = this.merge(this.merge(t1, t2), t3);\n  }\n\n  cutAndPaste(l, r, targetIndex) {\n    const [t1, t23] = this.split(this._root, l);\n    const [t2, t3] = this.split(t23, r - l + 1);\n    const rem = this.merge(t1, t3);\n    const [p1, p2] = this.split(rem, targetIndex);\n    this._root = this.merge(this.merge(p1, t2), p2);\n  }\n\n  rangeSum(l, r) {\n    if (l < 0 || r >= this.size || l > r) return 0;\n    const [t1, t23] = this.split(this._root, l);\n    const [t2, t3] = this.split(t23, r - l + 1);\n    const ans = this._sm(t2);\n    this._root = this.merge(this.merge(t1, t2), t3);\n    return ans;\n  }\n\n  toArray() {\n    const out = [];\n    const dfs = (t) => {\n      if (!t) return;\n      this._push(t);\n      dfs(t.left);\n      out.push(t.value);\n      dfs(t.right);\n    };\n    dfs(this._root);\n    return out;\n  }\n}\n\nmodule.exports = { ImplicitTreapRope };\n",
      "test.js": "'use strict';\n\nconst exported = require('./index.js');\nObject.assign(globalThis, exported);\n\n'use strict';\n\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  const rope = new ImplicitTreapRope([1, 2, 3, 4, 5, 6, 7, 8]);\n  assert(rope.size === 8, 'initial size 8');\n  assert(rope.rangeSum(2, 5) === 3 + 4 + 5 + 6, 'rangeSum [2, 5] === 18');\n\n  rope.reverseRange(1, 6); // [1, 7, 6, 5, 4, 3, 2, 8]\n  assert(JSON.stringify(rope.toArray()) === JSON.stringify([1, 7, 6, 5, 4, 3, 2, 8]), 'reverseRange [1, 6]');\n  assert(rope.rangeSum(1, 4) === 7 + 6 + 5 + 4, 'rangeSum after reverse');\n\n  rope.insertAt(3, 99); // [1, 7, 6, 99, 5, 4, 3, 2, 8]\n  assert(rope.get(3) === 99, 'insertAt(3, 99)');\n  const removed = rope.deleteAt(3);\n  assert(removed === 99, 'deleteAt(3) returns 99');\n\n  rope.cutAndPaste(1, 3, 5); // cut [7,6,5], remaining [1,4,3,2,8], paste at 5 -> [1,4,3,2,8,7,6,5]\n  assert(JSON.stringify(rope.toArray()) === JSON.stringify([1, 4, 3, 2, 8, 7, 6, 5]), 'cutAndPaste');\n\n  return { passed: 6, total: 6 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n\nif (require.main === module) {\n  const res = runTests();\n  console.log('All tests passed:', res);\n}\n\n",
