    "mainFile": "index.js",
    "starterCode": "'use strict';\n\nclass FenwickRangeTree {\n  constructor(initialArrayOrSize = 0) {\n    if (Array.isArray(initialArrayOrSize)) {\n      this._n = initialArrayOrSize.length;\n      this._b1 = new Float64Array(this._n + 1);\n      this._b2 = new Float64Array(this._n + 1);\n      this._buildFromArray(initialArrayOrSize);\n    } else {\n      this._n = initialArrayOrSize;\n      this._b1 = new Float64Array(this._n + 1);\n      this._b2 = new Float64Array(this._n + 1);\n    }\n  }\n\n  get size() { return this._n; }\n\n  _buildFromArray(arr) {\n    // TODO (Step 1): Build difference array in O(n) and propagate to immediate parent j = i + (i & -i)\n  }\n\n  _add(bit, idx1Based, delta) {\n    // TODO (Step 2): Add delta to bit at idx1Based, advancing idx += idx & -idx\n  }\n\n  _sum(bit, idx1Based) {\n    // TODO (Step 2): Sum bit[1..idx1Based], stepping idx -= idx & -idx\n    return 0;\n  }\n\n  rangeAdd(l, r, delta) {\n    // TODO (Step 3): Add delta to 0-indexed range [l, r] using dual BITs _b1 and _b2\n  }\n\n  pointAdd(index, delta) {\n    this.rangeAdd(index, index, delta);\n  }\n\n  prefixSum(index) {\n    // TODO (Step 3): Compute prefix sum [0..index] (0-indexed) using _sum(_b1, k)*k - _sum(_b2, k)\n    return 0;\n  }\n\n  rangeSum(l, r) {\n    if (l > r) return 0;\n    return this.prefixSum(r) - (l > 0 ? this.prefixSum(l - 1) : 0);\n  }\n\n  lowerBoundPrefix(targetSum) {\n    // TODO (Step 4): Binary lifting in O(log n) on a point-BIT view to find smallest 0-based index\n    // whose prefix sum >= targetSum (assuming non-negative elements)\n    return this._n;\n  }\n}\n\nmodule.exports = { FenwickRangeTree };\n",
    "solutionCode": "'use strict';\n\nclass FenwickRangeTree {\n  constructor(initialArrayOrSize = 0) {\n    if (Array.isArray(initialArrayOrSize)) {\n      this._n = initialArrayOrSize.length;\n      this._b1 = new Float64Array(this._n + 1);\n      this._b2 = new Float64Array(this._n + 1);\n      this._buildFromArray(initialArrayOrSize);\n    } else {\n      this._n = initialArrayOrSize;\n      this._b1 = new Float64Array(this._n + 1);\n      this._b2 = new Float64Array(this._n + 1);\n    }\n  }\n\n  get size() { return this._n; }\n\n  _buildFromArray(arr) {\n    for (let i = 1; i <= this._n; i++) {\n      const prev = i > 1 ? arr[i - 2] : 0;\n      const diff = arr[i - 1] - prev;\n      this._b1[i] += diff;\n      this._b2[i] += diff * (i - 1);\n      const parent = i + (i & -i);\n      if (parent <= this._n) {\n        this._b1[parent] += this._b1[i];\n        this._b2[parent] += this._b2[i];\n      }\n    }\n  }\n\n  _add(bit, idx, delta) {\n    for (let i = idx; i <= this._n; i += i & -i) {\n      bit[i] += delta;\n    }\n  }\n\n  _sum(bit, idx) {\n    let s = 0;\n    for (let i = idx; i > 0; i -= i & -i) {\n      s += bit[i];\n    }\n    return s;\n  }\n\n  rangeAdd(l, r, delta) {\n    if (l < 0 || r >= this._n || l > r) return;\n    const L = l + 1;\n    const R = r + 1;\n    this._add(this._b1, L, delta);\n    this._add(this._b1, R + 1, -delta);\n    this._add(this._b2, L, delta * (L - 1));\n    this._add(this._b2, R + 1, -delta * R);\n  }\n\n  pointAdd(index, delta) {\n    this.rangeAdd(index, index, delta);\n  }\n\n  prefixSum(index) {\n    if (index < 0) return 0;\n    const k = Math.min(this._n, index + 1);\n    return this._sum(this._b1, k) * k - this._sum(this._b2, k);\n  }\n\n  rangeSum(l, r) {\n    if (l > r) return 0;\n    return this.prefixSum(r) - (l > 0 ? this.prefixSum(l - 1) : 0);\n  }\n\n  lowerBoundPrefix(targetSum) {\n    if (targetSum <= 0) return 0;\n    // Build a point-prefix lookup via binary lifting on prefixSum\n    let pos = 0;\n    let bitMask = 1;\n    while ((bitMask << 1) <= this._n) bitMask <<= 1;\n    for (let step = bitMask; step > 0; step >>= 1) {\n      const next = pos + step;\n      if (next <= this._n && this.prefixSum(next - 1) < targetSum) {\n        pos = next;\n      }\n    }\n    return pos; // 0-indexed position where prefixSum(pos) >= targetSum, or _n if not reached\n  }\n}\n\nmodule.exports = { FenwickRangeTree };\n",
    "testHarness": "'use strict';\n\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  const init = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3];\n  const ref = [...init];\n  const ft = new FenwickRangeTree(init);\n\n  const checkAll = () => {\n    for (let l = 0; l < ref.length; l++) {\n      let s = 0;\n      for (let r = l; r < ref.length; r++) {\n        s += ref[r];\n        assert(Math.abs(ft.rangeSum(l, r) - s) < 1e-9, `rangeSum(${l},${r}) expected ${s}, got ${ft.rangeSum(l, r)}`);\n      }\n    }\n  };\n  checkAll();\n\n  // Range updates\n  const applyRange = (l, r, d) => {\n    ft.rangeAdd(l, r, d);\n    for (let i = l; i <= r; i++) ref[i] += d;\n  };\n  applyRange(2, 7, 10);\n  applyRange(0, 4, -2);\n  applyRange(5, 9, 6);\n  checkAll();\n\n  // Binary lifting test on positive weights\n  const weights = [5, 2, 8, 4, 1, 9, 3]; // prefixes: 5, 7, 15, 19, 20, 29, 32\n  const wft = new FenwickRangeTree(weights);\n  assert(wft.lowerBoundPrefix(1) === 0, 'lowerBoundPrefix(1) === 0');\n  assert(wft.lowerBoundPrefix(5) === 0, 'lowerBoundPrefix(5) === 0');\n  assert(wft.lowerBoundPrefix(6) === 1, 'lowerBoundPrefix(6) === 1');\n  assert(wft.lowerBoundPrefix(15) === 2, 'lowerBoundPrefix(15) === 2');\n  assert(wft.lowerBoundPrefix(16) === 3, 'lowerBoundPrefix(16) === 3');\n  assert(wft.lowerBoundPrefix(33) === weights.length, 'lowerBoundPrefix(33) === n');\n\n  return { passed: 5, total: 5 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n",
