      "index.js": "'use strict';\n\nclass LazySegmentTree {\n  constructor(arr) {\n    this._n = arr.length;\n    const size = 4 * Math.max(1, this._n);\n    this._sum = new Float64Array(size);\n    this._min = new Float64Array(size);\n    this._max = new Float64Array(size);\n    this._lazyMul = new Float64Array(size).fill(1);\n    this._lazyAdd = new Float64Array(size).fill(0);\n    if (this._n > 0) this._build(1, 0, this._n - 1, arr);\n  }\n\n  _pull(node) {\n    const l = node << 1, r = l | 1;\n    this._sum[node] = this._sum[l] + this._sum[r];\n    this._min[node] = Math.min(this._min[l], this._min[r]);\n    this._max[node] = Math.max(this._max[l], this._max[r]);\n  }\n\n  _build(node, start, end, arr) {\n    if (start === end) {\n      this._sum[node] = this._min[node] = this._max[node] = arr[start];\n      return;\n    }\n    const mid = (start + end) >> 1;\n    this._build(node << 1, start, mid, arr);\n    this._build((node << 1) | 1, mid + 1, end, arr);\n    this._pull(node);\n  }\n\n  _applyAffine(node, len, mul, add) {\n    this._sum[node] = this._sum[node] * mul + add * len;\n    const mn = this._min[node] * mul + add;\n    const mx = this._max[node] * mul + add;\n    this._min[node] = Math.min(mn, mx);\n    this._max[node] = Math.max(mn, mx);\n    this._lazyMul[node] *= mul;\n    this._lazyAdd[node] = this._lazyAdd[node] * mul + add;\n  }\n\n  _push(node, start, end) {\n    const mul = this._lazyMul[node];\n    const add = this._lazyAdd[node];\n    if (mul === 1 && add === 0) return;\n    const mid = (start + end) >> 1;\n    this._applyAffine(node << 1, mid - start + 1, mul, add);\n    this._applyAffine((node << 1) | 1, end - mid, mul, add);\n    this._lazyMul[node] = 1;\n    this._lazyAdd[node] = 0;\n  }\n\n  rangeAffine(ql, qr, mul, add) {\n    if (ql < 0 || qr >= this._n || ql > qr) return;\n    this._update(1, 0, this._n - 1, ql, qr, mul, add);\n  }\n\n  _update(node, start, end, ql, qr, mul, add) {\n    if (ql <= start && end <= qr) {\n      this._applyAffine(node, end - start + 1, mul, add);\n      return;\n    }\n    this._push(node, start, end);\n    const mid = (start + end) >> 1;\n    if (ql <= mid) this._update(node << 1, start, mid, ql, qr, mul, add);\n    if (qr > mid) this._update((node << 1) | 1, mid + 1, end, ql, qr, mul, add);\n    this._pull(node);\n  }\n\n  rangeAdd(ql, qr, delta) { this.rangeAffine(ql, qr, 1, delta); }\n  rangeMultiply(ql, qr, factor) { this.rangeAffine(ql, qr, factor, 0); }\n  rangeAssign(ql, qr, val) { this.rangeAffine(ql, qr, 0, val); }\n\n  queryRange(ql, qr) {\n    if (ql < 0 || qr >= this._n || ql > qr) return { sum: 0, min: Infinity, max: -Infinity };\n    return this._query(1, 0, this._n - 1, ql, qr);\n  }\n\n  _query(node, start, end, ql, qr) {\n    if (ql <= start && end <= qr) {\n      return { sum: this._sum[node], min: this._min[node], max: this._max[node] };\n    }\n    this._push(node, start, end);\n    const mid = (start + end) >> 1;\n    let res = { sum: 0, min: Infinity, max: -Infinity };\n    if (ql <= mid) {\n      const leftRes = this._query(node << 1, start, mid, ql, qr);\n      res.sum += leftRes.sum;\n      res.min = Math.min(res.min, leftRes.min);\n      res.max = Math.max(res.max, leftRes.max);\n    }\n    if (qr > mid) {\n      const rightRes = this._query((node << 1) | 1, mid + 1, end, ql, qr);\n      res.sum += rightRes.sum;\n      res.min = Math.min(res.min, rightRes.min);\n      res.max = Math.max(res.max, rightRes.max);\n    }\n    return res;\n  }\n\n  findFirstAtLeast(ql, qr, threshold) {\n    if (ql < 0 || qr >= this._n || ql > qr) return -1;\n    return this._walk(1, 0, this._n - 1, ql, qr, threshold);\n  }\n\n  _walk(node, start, end, ql, qr, threshold) {\n    if (end < ql || start > qr || this._max[node] < threshold) return -1;\n    if (start === end) return start;\n    this._push(node, start, end);\n    const mid = (start + end) >> 1;\n    const leftAns = this._walk(node << 1, start, mid, ql, qr, threshold);\n    if (leftAns !== -1) return leftAns;\n    return this._walk((node << 1) | 1, mid + 1, end, ql, qr, threshold);\n  }\n}\n\nmodule.exports = { LazySegmentTree };\n",
      "test.js": "'use strict';\n\nconst exported = require('./index.js');\nObject.assign(globalThis, exported);\n\n'use strict';\n\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  const arr = [2, 5, 1, 8, 3, 7, 4, 6];\n  const ref = [...arr];\n  const st = new LazySegmentTree(arr);\n\n  const verifyAll = () => {\n    for (let l = 0; l < ref.length; l++) {\n      for (let r = l; r < ref.length; r++) {\n        const sub = ref.slice(l, r + 1);\n        const sum = sub.reduce((a, b) => a + b, 0);\n        const min = Math.min(...sub);\n        const max = Math.max(...sub);\n        const q = st.queryRange(l, r);\n        assert(Math.abs(q.sum - sum) < 1e-9, `sum [${l},${r}]`);\n        assert(Math.abs(q.min - min) < 1e-9, `min [${l},${r}]`);\n        assert(Math.abs(q.max - max) < 1e-9, `max [${l},${r}]`);\n      }\n    }\n  };\n  verifyAll();\n\n  // Range Add\n  st.rangeAdd(1, 5, 4);\n  for (let i = 1; i <= 5; i++) ref[i] += 4;\n  verifyAll();\n\n  // Range Multiply\n  st.rangeMultiply(2, 6, 3);\n  for (let i = 2; i <= 6; i++) ref[i] *= 3;\n  verifyAll();\n\n  // Range Assign (mul = 0, add = val)\n  st.rangeAssign(0, 3, 10);\n  for (let i = 0; i <= 3; i++) ref[i] = 10;\n  verifyAll();\n\n  // Tree walk findFirstAtLeast\n  for (let l = 0; l < ref.length; l++) {\n    for (let t = 0; t <= 40; t += 5) {\n      let expected = -1;\n      for (let i = l; i < ref.length; i++) {\n        if (ref[i] >= t) { expected = i; break; }\n      }\n      assert(st.findFirstAtLeast(l, ref.length - 1, t) === expected, `findFirstAtLeast(${l}, ${t})`);\n    }\n  }\n\n  return { passed: 5, total: 5 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n\nif (require.main === module) {\n  const res = runTests();\n  console.log('All tests passed:', res);\n}\n\n",
      "demo.js": "'use strict';\nconst { LazySegmentTree } = require('./index.js');\n\nconst st = new LazySegmentTree([1, 2, 3, 4, 5, 6, 7, 8]);\nst.rangeAdd(0, 4, 10);\nst.rangeMultiply(2, 6, 2);\nconsole.log('Query [0..7]:', st.queryRange(0, 7));\nconsole.log('First index >= 25 in [0..7]:', st.findFirstAtLeast(0, 7, 25));\n"
