    "starterCode": "'use strict';\n\nclass PSTNode {\n  constructor(sum = 0, left = null, right = null) {\n    this.sum = sum;\n    this.left = left;\n    this.right = right;\n  }\n}\n\nclass PersistentSegmentTree {\n  constructor(initialArray = []) {\n    this._n = initialArray.length;\n    this._roots = [];\n    if (this._n > 0) {\n      this._roots.push(this._build(0, this._n - 1, initialArray));\n    }\n  }\n\n  get versionCount() { return this._roots.length; }\n\n  _build(l, r, arr) {\n    if (l === r) return new PSTNode(arr[l], null, null);\n    const mid = (l + r) >> 1;\n    const left = this._build(l, mid, arr);\n    const right = this._build(mid + 1, r, arr);\n    return new PSTNode(left.sum + right.sum, left, right);\n  }\n\n  update(version, index, newValue) {\n    // TODO (Step 1): Path-copy from _roots[version], creating O(log n) new PSTNodes,\n    // push the new root to _roots, and return the new version ID.\n    return 0;\n  }\n\n  add(version, index, delta) {\n    // TODO (Step 2): Path-copy from _roots[version], adding delta to leaf at index\n    return 0;\n  }\n\n  queryRange(version, ql, qr) {\n    // TODO (Step 3): Query sum in [ql, qr] on _roots[version] in O(log n)\n    return 0;\n  }\n}\n\nclass RangeKthSmallestIndex {\n  constructor(arr) {\n    // TODO (Step 4): Coordinate-compress arr and build prefix persistent frequency trees\n    // so rangeKth(l, r, k) (0-indexed k-th smallest in arr[l..r]) runs in O(log U)\n  }\n\n  rangeKth(l, r, k) {\n    // TODO (Step 4): Walk root[r+1] and root[l] in lockstep to find k-th smallest value\n    return undefined;\n  }\n}\n\nmodule.exports = { PersistentSegmentTree, RangeKthSmallestIndex };\n",
    "solutionCode": "'use strict';\n\nclass PSTNode {\n  constructor(sum = 0, left = null, right = null) {\n    this.sum = sum;\n    this.left = left;\n    this.right = right;\n  }\n}\n\nclass PersistentSegmentTree {\n  constructor(initialArray = []) {\n    this._n = initialArray.length;\n    this._roots = [];\n    if (this._n > 0) {\n      this._roots.push(this._build(0, this._n - 1, initialArray));\n    }\n  }\n\n  get versionCount() { return this._roots.length; }\n\n  _build(l, r, arr) {\n    if (l === r) return new PSTNode(arr[l], null, null);\n    const mid = (l + r) >> 1;\n    const left = this._build(l, mid, arr);\n    const right = this._build(mid + 1, r, arr);\n    return new PSTNode(left.sum + right.sum, left, right);\n  }\n\n  update(version, index, newValue) {\n    const baseRoot = this._roots[version];\n    const newRoot = this._update(baseRoot, 0, this._n - 1, index, newValue, false);\n    this._roots.push(newRoot);\n    return this._roots.length - 1;\n  }\n\n  add(version, index, delta) {\n    const baseRoot = this._roots[version];\n    const newRoot = this._update(baseRoot, 0, this._n - 1, index, delta, true);\n    this._roots.push(newRoot);\n    return this._roots.length - 1;\n  }\n\n  _update(node, l, r, idx, val, isDelta) {\n    if (l === r) {\n      return new PSTNode(isDelta ? node.sum + val : val, null, null);\n    }\n    const mid = (l + r) >> 1;\n    if (idx <= mid) {\n      const newLeft = this._update(node.left, l, mid, idx, val, isDelta);\n      return new PSTNode(newLeft.sum + node.right.sum, newLeft, node.right);\n    } else {\n      const newRight = this._update(node.right, mid + 1, r, idx, val, isDelta);\n      return new PSTNode(node.left.sum + newRight.sum, node.left, newRight);\n    }\n  }\n\n  queryRange(version, ql, qr) {\n    if (ql < 0 || qr >= this._n || ql > qr) return 0;\n    return this._query(this._roots[version], 0, this._n - 1, ql, qr);\n  }\n\n  _query(node, l, r, ql, qr) {\n    if (!node || ql > r || qr < l) return 0;\n    if (ql <= l && r <= qr) return node.sum;\n    const mid = (l + r) >> 1;\n    return this._query(node.left, l, mid, ql, qr) +\n           this._query(node.right, mid + 1, r, ql, qr);\n  }\n}\n\nclass RangeKthSmallestIndex {\n  constructor(arr) {\n    this._sortedUnique = Array.from(new Set(arr)).sort((a, b) => a - b);\n    this._u = this._sortedUnique.length;\n    this._pst = new PersistentSegmentTree(new Array(Math.max(1, this._u)).fill(0));\n    // _pst._roots[0] is empty counts; _pst._roots[i + 1] has prefix arr[0..i]\n    for (let i = 0; i < arr.length; i++) {\n      const rank = this._rankOf(arr[i]);\n      this._pst.add(i, rank, 1);\n    }\n  }\n\n  _rankOf(val) {\n    let lo = 0, hi = this._u - 1;\n    while (lo <= hi) {\n      const mid = (lo + hi) >> 1;\n      if (this._sortedUnique[mid] === val) return mid;\n      if (this._sortedUnique[mid] < val) lo = mid + 1;\n      else hi = mid - 1;\n    }\n    return lo;\n  }\n\n  rangeKth(l, r, k) {\n    if (k < 0 || k > r - l) return undefined;\n    const rootL = this._pst._roots[l];\n    const rootR = this._pst._roots[r + 1];\n    let lo = 0, hi = this._u - 1;\n    let u = rootL, v = rootR, rem = k;\n    while (lo < hi) {\n      const mid = (lo + hi) >> 1;\n      const leftCount = v.left.sum - u.left.sum;\n      if (rem < leftCount) {\n        u = u.left;\n        v = v.left;\n        hi = mid;\n      } else {\n        rem -= leftCount;\n        u = u.right;\n        v = v.right;\n        lo = mid + 1;\n      }\n    }\n    return this._sortedUnique[lo];\n  }\n}\n\nmodule.exports = { PersistentSegmentTree, RangeKthSmallestIndex };\n",
    "testHarness": "'use strict';\n\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  const pst = new PersistentSegmentTree([10, 20, 30, 40, 50]);\n  const v1 = pst.update(0, 2, 100); // [10, 20, 100, 40, 50]\n  const v2 = pst.add(v1, 4, 25);    // [10, 20, 100, 40, 75]\n  const v3 = pst.update(0, 0, 99);  // branched from v0: [99, 20, 30, 40, 50]\n\n  assert(pst.queryRange(0, 0, 4) === 150, 'v0 sum is untouched (150)');\n  assert(pst.queryRange(v1, 0, 4) === 220, 'v1 sum is 220');\n  assert(pst.queryRange(v2, 1, 4) === 235, 'v2 sum [1..4] is 235');\n  assert(pst.queryRange(v3, 0, 2) === 149, 'v3 branched from v0 sum [0..2] is 149');\n\n  // Static Range K-th Smallest test\n  const sample = [42, 15, 73, 8, 91, 15, 64, 29, 50, 12];\n  const kthIdx = new RangeKthSmallestIndex(sample);\n  for (let l = 0; l < sample.length; l++) {\n    for (let r = l; r < sample.length; r++) {\n      const sortedSub = sample.slice(l, r + 1).sort((a, b) => a - b);\n      for (let k = 0; k < sortedSub.length; k++) {\n        assert(kthIdx.rangeKth(l, r, k) === sortedSub[k], `rangeKth(${l},${r},${k})`);\n      }\n    }\n  }\n\n  return { passed: 5, total: 5 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n",
