    "starterCode": "'use strict';\n\nclass AhoCorasickNode {\n  constructor() {\n    this.next = new Map();\n    this.fail = 0;\n    this.outputLink = 0;\n    this.outputs = []; // pattern indices ending exactly here\n  }\n}\n\nclass AhoCorasickScanner {\n  constructor(patterns = []) {\n    this._nodes = [new AhoCorasickNode()];\n    this._patterns = [];\n    this._compiled = false;\n    for (const p of patterns) this.addPattern(p);\n    if (patterns.length > 0) this.compile();\n  }\n\n  addPattern(pattern) {\n    // TODO (Step 1): Insert non-empty pattern into Trie (_nodes), append pattern ID to leaf outputs\n    return -1;\n  }\n\n  compile() {\n    // TODO (Step 2): Level-order BFS from root's children to compute fail links and outputLink shortcuts\n  }\n\n  _step(state, ch) {\n    // TODO (Step 3): Follow fail links until state has transition on ch or reaches root (0)\n    return 0;\n  }\n\n  search(text) {\n    // TODO (Step 4): Scan text in O(|T| + matches), traversing outputLink chain at each state\n    // Return array of { pattern, patternId, start, end }\n    return [];\n  }\n\n  countMatches(text) {\n    return this.search(text).length;\n  }\n}\n\nmodule.exports = { AhoCorasickScanner };\n",
    "solutionCode": "'use strict';\n\nclass AhoCorasickNode {\n  constructor() {\n    this.next = new Map();\n    this.fail = 0;\n    this.outputLink = 0;\n    this.outputs = [];\n  }\n}\n\nclass AhoCorasickScanner {\n  constructor(patterns = []) {\n    this._nodes = [new AhoCorasickNode()];\n    this._patterns = [];\n    this._compiled = false;\n    for (const p of patterns) this.addPattern(p);\n    if (patterns.length > 0) this.compile();\n  }\n\n  addPattern(pattern) {\n    if (!pattern || pattern.length === 0) return -1;\n    this._compiled = false;\n    const id = this._patterns.length;\n    this._patterns.push(pattern);\n    let u = 0;\n    for (let i = 0; i < pattern.length; i++) {\n      const ch = pattern[i];\n      if (!this._nodes[u].next.has(ch)) {\n        this._nodes[u].next.set(ch, this._nodes.length);\n        this._nodes.push(new AhoCorasickNode());\n      }\n      u = this._nodes[u].next.get(ch);\n    }\n    this._nodes[u].outputs.push(id);\n    return id;\n  }\n\n  compile() {\n    const queue = [];\n    for (const [, v] of this._nodes[0].next) {\n      this._nodes[v].fail = 0;\n      this._nodes[v].outputLink = 0;\n      queue.push(v);\n    }\n    let head = 0;\n    while (head < queue.length) {\n      const u = queue[head++];\n      for (const [ch, v] of this._nodes[u].next) {\n        queue.push(v);\n        let f = this._nodes[u].fail;\n        while (f !== 0 && !this._nodes[f].next.has(ch)) {\n          f = this._nodes[f].fail;\n        }\n        const failTarget = this._nodes[f].next.get(ch) || 0;\n        this._nodes[v].fail = failTarget === v ? 0 : failTarget;\n        const ft = this._nodes[v].fail;\n        this._nodes[v].outputLink = this._nodes[ft].outputs.length > 0\n          ? ft\n          : this._nodes[ft].outputLink;\n      }\n    }\n    this._compiled = true;\n  }\n\n  _step(state, ch) {\n    let u = state;\n    while (u !== 0 && !this._nodes[u].next.has(ch)) {\n      u = this._nodes[u].fail;\n    }\n    return this._nodes[u].next.get(ch) || 0;\n  }\n\n  search(text) {\n    if (!this._compiled) this.compile();\n    const matches = [];\n    let state = 0;\n    for (let i = 0; i < text.length; i++) {\n      state = this._step(state, text[i]);\n      for (let temp = state; temp !== 0; temp = this._nodes[temp].outputLink) {\n        for (const patId of this._nodes[temp].outputs) {\n          const pat = this._patterns[patId];\n          matches.push({\n            pattern: pat,\n            patternId: patId,\n            start: i - pat.length + 1,\n            end: i\n          });\n        }\n      }\n    }\n    return matches;\n  }\n\n  countMatches(text) {\n    return this.search(text).length;\n  }\n}\n\nmodule.exports = { AhoCorasickScanner };\n",
    "testHarness": "'use strict';\n\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  // Classic Aho-Corasick paper benchmark: [\"he\", \"she\", \"his\", \"hers\"] in \"ushers\"\n  const scanner = new AhoCorasickScanner(['he', 'she', 'his', 'hers']);\n  const hits = scanner.search('ushers');\n  const foundPatterns = hits.map(h => `${h.pattern}@${h.start}`).sort();\n  assert(\n    JSON.stringify(foundPatterns) === JSON.stringify(['he@2', 'hers@2', 'she@1']),\n    'classic ushers test: ' + JSON.stringify(foundPatterns)\n  );\n\n  // Overlapping nested substrings\n  const dna = new AhoCorasickScanner(['A', 'AA', 'AAA', 'ABA', 'B']);\n  const text = 'AAABAAA';\n  const actual = dna.search(text);\n  // Brute force verification\n  const expected = [];\n  for (const pat of ['A', 'AA', 'AAA', 'ABA', 'B']) {\n    for (let i = 0; i + pat.length <= text.length; i++) {\n      if (text.slice(i, i + pat.length) === pat) {\n        expected.push(`${pat}@${i}`);\n      }\n    }\n  }\n  const actualKeys = actual.map(m => `${m.pattern}@${m.start}`).sort();\n  expected.sort();\n  assert(JSON.stringify(actualKeys) === JSON.stringify(expected), 'overlapping DNA matches');\n\n  return { passed: 4, total: 4 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n",
