    "solutionCode": "'use strict';\n\nclass SuffixArrayIndex {\n  constructor(text) {\n    this.text = String(text);\n    this.n = this.text.length;\n    this.sa = this._buildSuffixArray();\n    this.rank = new Int32Array(this.n);\n    for (let i = 0; i < this.n; i++) this.rank[this.sa[i]] = i;\n    this.lcp = this._buildKasaiLCP();\n    this._rmq = this._buildSparseTable(this.lcp);\n  }\n\n  _buildSuffixArray() {\n    const n = this.n;\n    if (n === 0) return [];\n    const sa = Array.from({ length: n }, (_, i) => i);\n    let rnk = new Int32Array(n);\n    let tmp = new Int32Array(n);\n    for (let i = 0; i < n; i++) rnk[i] = this.text.charCodeAt(i);\n\n    for (let k = 1; k < n; k <<= 1) {\n      const cmp = (i, j) => {\n        if (rnk[i] !== rnk[j]) return rnk[i] - rnk[j];\n        const ri = i + k < n ? rnk[i + k] : -1;\n        const rj = j + k < n ? rnk[j + k] : -1;\n        return ri - rj;\n      };\n      sa.sort(cmp);\n      tmp[sa[0]] = 0;\n      for (let i = 1; i < n; i++) {\n        tmp[sa[i]] = tmp[sa[i - 1]] + (cmp(sa[i - 1], sa[i]) < 0 ? 1 : 0);\n      }\n      for (let i = 0; i < n; i++) rnk[i] = tmp[i];\n      if (rnk[sa[n - 1]] === n - 1) break;\n    }\n    return sa;\n  }\n\n  _buildKasaiLCP() {\n    const n = this.n;\n    if (n <= 1) return [];\n    const lcp = new Int32Array(n - 1);\n    let h = 0;\n    for (let i = 0; i < n; i++) {\n      const r = this.rank[i];\n      if (r === n - 1) {\n        h = 0;\n        continue;\n      }\n      const j = this.sa[r + 1];\n      while (i + h < n && j + h < n && this.text.charCodeAt(i + h) === this.text.charCodeAt(j + h)) {\n        h++;\n      }\n      lcp[r] = h;\n      if (h > 0) h--;\n    }\n    return Array.from(lcp);\n  }\n\n  _buildSparseTable(arr) {\n    const m = arr.length;\n    if (m === 0) return [];\n    const maxK = Math.floor(Math.log2(m)) + 1;\n    const st = Array.from({ length: maxK }, () => new Int32Array(m));\n    for (let i = 0; i < m; i++) st[0][i] = arr[i];\n    for (let k = 1; k < maxK; k++) {\n      const half = 1 << (k - 1);\n      const span = 1 << k;\n      for (let i = 0; i + span <= m; i++) {\n        st[k][i] = Math.min(st[k - 1][i], st[k - 1][i + half]);\n      }\n    }\n    return st;\n  }\n\n  lcpOfSuffixes(i, j) {\n    if (i < 0 || j < 0 || i >= this.n || j >= this.n) return 0;\n    if (i === j) return this.n - i;\n    let l = this.rank[i], r = this.rank[j];\n    if (l > r) { const t = l; l = r; r = t; }\n    r--; // query inclusive [l, r] on lcp array\n    const len = r - l + 1;\n    const k = Math.floor(Math.log2(len));\n    return Math.min(this._rmq[k][l], this._rmq[k][r - (1 << k) + 1]);\n  }\n\n  search(pattern) {\n    if (!pattern || pattern.length === 0 || this.n === 0) return [];\n    const m = pattern.length;\n    let lo = 0, hi = this.n;\n    while (lo < hi) {\n      const mid = (lo + hi) >> 1;\n      const sub = this.text.slice(this.sa[mid], this.sa[mid] + m);\n      if (sub < pattern) lo = mid + 1;\n      else hi = mid;\n    }\n    const start = lo;\n    hi = this.n;\n    while (lo < hi) {\n      const mid = (lo + hi) >> 1;\n      const sub = this.text.slice(this.sa[mid], this.sa[mid] + m);\n      if (sub <= pattern) lo = mid + 1;\n      else hi = mid;\n    }\n    const end = lo;\n    return this.sa.slice(start, end).sort((a, b) => a - b);\n  }\n\n  countDistinctSubstrings() {\n    const total = (this.n * (this.n + 1)) / 2;\n    let shared = 0;\n    for (let i = 0; i < this.lcp.length; i++) shared += this.lcp[i];\n    return total - shared;\n  }\n\n  longestRepeatedSubstring() {\n    let bestLen = 0, bestPos = 0;\n    for (let i = 0; i < this.lcp.length; i++) {\n      if (this.lcp[i] > bestLen) {\n        bestLen = this.lcp[i];\n        bestPos = this.sa[i];\n      }\n    }\n    return this.text.slice(bestPos, bestPos + bestLen);\n  }\n}\n\nmodule.exports = { SuffixArrayIndex };\n",
    "testHarness": "'use strict';\n\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  const idx = new SuffixArrayIndex('banana');\n  // Suffixes of \"banana\":\n  // 5: a, 3: ana, 1: anana, 0: banana, 4: na, 2: nana\n  assert(JSON.stringify(idx.sa) === JSON.stringify([5, 3, 1, 0, 4, 2]), 'SA of banana');\n  assert(JSON.stringify(idx.lcp) === JSON.stringify([1, 3, 0, 0, 2]), 'LCP of banana');\n  assert(idx.countDistinctSubstrings() === 15, 'banana has 15 distinct substrings');\n  assert(idx.longestRepeatedSubstring() === 'ana', 'LRS of banana is ana');\n  assert(JSON.stringify(idx.search('ana')) === JSON.stringify([1, 3]), 'search(\"ana\")');\n  assert(idx.lcpOfSuffixes(1, 3) === 3, 'LCP of \"anana\" and \"ana\" is 3');\n  assert(idx.lcpOfSuffixes(2, 4) === 2, 'LCP of \"nana\" and \"na\" is 2');\n\n  // Verify distinct substrings against Set on \"mississippi\"\n  const s = 'mississippi';\n  const saIdx = new SuffixArrayIndex(s);\n  const bruteSet = new Set();\n  for (let i = 0; i < s.length; i++) {\n    for (let j = i + 1; j <= s.length; j++) bruteSet.add(s.slice(i, j));\n  }\n  assert(saIdx.countDistinctSubstrings() === bruteSet.size, 'distinct substrings of mississippi');\n\n  return { passed: 6, total: 6 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n",
