      "index.js": "'use strict';\n\nclass RollbackDSU {\n  constructor(n) {\n    this.n = n;\n    this.parent = Int32Array.from({ length: n }, (_, i) => i);\n    this.sz = new Int32Array(n).fill(1);\n    this.components = n;\n    this._history = []; // stack of { child, parent, oldParentSize } or null if no-op\n  }\n\n  find(x) {\n    // TODO (Step 1): Walk parent pointers WITHOUT path compression so tree mutations are O(1) reversible\n    return x;\n  }\n\n  connected(u, v) {\n    return this.find(u) === this.find(v);\n  }\n\n  union(u, v) {\n    // TODO (Step 1): Union by size; push mutation record onto _history and decrement components\n    return false;\n  }\n\n  snapshot() {\n    return this._history.length;\n  }\n\n  rollback(targetSnapshot) {\n    // TODO (Step 2): Undo mutations from _history until _history.length === targetSnapshot\n  }\n}\n\nclass OfflineDynamicConnectivity {\n  constructor(numVertices) {\n    this.n = numVertices;\n    this._events = []; // { type: 'add' | 'remove' | 'query', u, v }\n  }\n\n  addEdge(u, v) {\n    const a = Math.min(u, v), b = Math.max(u, v);\n    this._events.push({ type: 'add', u: a, v: b });\n  }\n\n  removeEdge(u, v) {\n    const a = Math.min(u, v), b = Math.max(u, v);\n    this._events.push({ type: 'remove', u: a, v: b });\n  }\n\n  queryComponents() {\n    this._events.push({ type: 'query', kind: 'components' });\n  }\n\n  queryConnected(u, v) {\n    this._events.push({ type: 'query', kind: 'connected', u, v });\n  }\n\n  solve() {\n    // TODO (Step 3 & 4): Map each edge addition/removal into time intervals [start, end],\n    // insert edge intervals into a Segment Tree over [0..numEvents-1], and DFS the tree\n    // using RollbackDSU.snapshot() / rollback() to answer all queries.\n    return [];\n  }\n}\n\nmodule.exports = { RollbackDSU, OfflineDynamicConnectivity };\n",
      "test.js": "'use strict';\n\nconst exported = require('./index.js');\nObject.assign(globalThis, exported);\n\n'use strict';\n\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  // Direct RollbackDSU test\n  const dsu = new RollbackDSU(5);\n  dsu.union(0, 1);\n  const s1 = dsu.snapshot();\n  dsu.union(1, 2);\n  dsu.union(3, 4);\n  assert(dsu.components === 2, '2 components after 3 unions');\n  assert(dsu.connected(0, 2) === true, '0 and 2 connected');\n  dsu.rollback(s1);\n  assert(dsu.components === 4, '4 components after rollback to s1');\n  assert(dsu.connected(0, 2) === false, '0 and 2 disconnected after rollback');\n  assert(dsu.connected(0, 1) === true, '0 and 1 still connected');\n\n  // Offline Dynamic Connectivity test\n  const odc = new OfflineDynamicConnectivity(4);\n  odc.addEdge(0, 1);\n  odc.addEdge(1, 2);\n  odc.queryComponents();         // -> 2 ({0,1,2}, {3})\n  odc.queryConnected(0, 2);      // -> true\n  odc.addEdge(2, 3);\n  odc.queryComponents();         // -> 1\n  odc.removeEdge(1, 2);\n  odc.queryComponents();         // -> 2 ({0,1}, {2,3})\n  odc.queryConnected(0, 3);      // -> false\n  odc.addEdge(0, 3);\n  odc.queryConnected(1, 2);      // -> true (via 1-0-3-2)\n\n  const ans = odc.solve();\n  assert(\n    JSON.stringify(ans) === JSON.stringify([2, true, 1, 2, false, true]),\n    'Offline dynamic connectivity answers: ' + JSON.stringify(ans)\n  );\n\n  return { passed: 5, total: 5 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n\nif (require.main === module) {\n  const res = runTests();\n  console.log('All tests passed:', res);\n}\n\n",
