      "index.js": "'use strict';\n\nclass RollbackDSU {\n  constructor(n) {\n    this.n = n;\n    this.parent = Int32Array.from({ length: n }, (_, i) => i);\n    this.sz = new Int32Array(n).fill(1);\n    this.components = n;\n    this._history = [];\n  }\n\n  find(x) {\n    while (this.parent[x] !== x) x = this.parent[x];\n    return x;\n  }\n\n  connected(u, v) {\n    return this.find(u) === this.find(v);\n  }\n\n  union(u, v) {\n    let ru = this.find(u);\n    let rv = this.find(v);\n    if (ru === rv) return false;\n    if (this.sz[ru] < this.sz[rv]) {\n      const t = ru; ru = rv; rv = t;\n    }\n    this._history.push({ child: rv, parent: ru, prevSize: this.sz[ru] });\n    this.parent[rv] = ru;\n    this.sz[ru] += this.sz[rv];\n    this.components--;\n    return true;\n  }\n\n  snapshot() {\n    return this._history.length;\n  }\n\n  rollback(targetSnapshot) {\n    while (this._history.length > targetSnapshot) {\n      const rec = this._history.pop();\n      this.parent[rec.child] = rec.child;\n      this.sz[rec.parent] = rec.prevSize;\n      this.components++;\n    }\n  }\n}\n\nclass OfflineDynamicConnectivity {\n  constructor(numVertices) {\n    this.n = numVertices;\n    this._events = [];\n  }\n\n  addEdge(u, v) {\n    const a = Math.min(u, v), b = Math.max(u, v);\n    this._events.push({ type: 'add', u: a, v: b });\n  }\n\n  removeEdge(u, v) {\n    const a = Math.min(u, v), b = Math.max(u, v);\n    this._events.push({ type: 'remove', u: a, v: b });\n  }\n\n  queryComponents() {\n    this._events.push({ type: 'query', kind: 'components' });\n  }\n\n  queryConnected(u, v) {\n    this._events.push({ type: 'query', kind: 'connected', u, v });\n  }\n\n  solve() {\n    const T = this._events.length;\n    if (T === 0) return [];\n    const tree = Array.from({ length: 4 * T }, () => []);\n\n    const insertInterval = (node, l, r, ql, qr, edge) => {\n      if (ql <= l && r <= qr) {\n        tree[node].push(edge);\n        return;\n      }\n      const mid = (l + r) >> 1;\n      if (ql <= mid) insertInterval(node << 1, l, mid, ql, qr, edge);\n      if (qr > mid) insertInterval((node << 1) | 1, mid + 1, r, ql, qr, edge);\n    };\n\n    const active = new Map(); // \"u:v\" -> stack of start times\n    for (let t = 0; t < T; t++) {\n      const ev = this._events[t];\n      if (ev.type === 'add') {\n        const key = `${ev.u}:${ev.v}`;\n        if (!active.has(key)) active.set(key, []);\n        active.get(key).push(t);\n      } else if (ev.type === 'remove') {\n        const key = `${ev.u}:${ev.v}`;\n        const stack = active.get(key);\n        if (stack && stack.length > 0) {\n          const start = stack.pop();\n          insertInterval(1, 0, T - 1, start, t - 1, { u: ev.u, v: ev.v });\n        }\n      }\n    }\n    for (const [key, stack] of active.entries()) {\n      const [u, v] = key.split(':').map(Number);\n      while (stack.length > 0) {\n        const start = stack.pop();\n        insertInterval(1, 0, T - 1, start, T - 1, { u, v });\n      }\n    }\n\n    const dsu = new RollbackDSU(this.n);\n    const answers = [];\n\n    const dfs = (node, l, r) => {\n      const snap = dsu.snapshot();\n      for (const edge of tree[node]) {\n        dsu.union(edge.u, edge.v);\n      }\n      if (l === r) {\n        const ev = this._events[l];\n        if (ev.type === 'query') {\n          if (ev.kind === 'components') answers.push(dsu.components);\n          else answers.push(dsu.connected(ev.u, ev.v));\n        }\n      } else {\n        const mid = (l + r) >> 1;\n        dfs(node << 1, l, mid);\n        dfs((node << 1) | 1, mid + 1, r);\n      }\n      dsu.rollback(snap);\n    };\n\n    dfs(1, 0, T - 1);\n    return answers;\n  }\n}\n\nmodule.exports = { RollbackDSU, OfflineDynamicConnectivity };\n",
      "test.js": "'use strict';\n\nconst exported = require('./index.js');\nObject.assign(globalThis, exported);\n\n'use strict';\n\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  // Direct RollbackDSU test\n  const dsu = new RollbackDSU(5);\n  dsu.union(0, 1);\n  const s1 = dsu.snapshot();\n  dsu.union(1, 2);\n  dsu.union(3, 4);\n  assert(dsu.components === 2, '2 components after 3 unions');\n  assert(dsu.connected(0, 2) === true, '0 and 2 connected');\n  dsu.rollback(s1);\n  assert(dsu.components === 4, '4 components after rollback to s1');\n  assert(dsu.connected(0, 2) === false, '0 and 2 disconnected after rollback');\n  assert(dsu.connected(0, 1) === true, '0 and 1 still connected');\n\n  // Offline Dynamic Connectivity test\n  const odc = new OfflineDynamicConnectivity(4);\n  odc.addEdge(0, 1);\n  odc.addEdge(1, 2);\n  odc.queryComponents();         // -> 2 ({0,1,2}, {3})\n  odc.queryConnected(0, 2);      // -> true\n  odc.addEdge(2, 3);\n  odc.queryComponents();         // -> 1\n  odc.removeEdge(1, 2);\n  odc.queryComponents();         // -> 2 ({0,1}, {2,3})\n  odc.queryConnected(0, 3);      // -> false\n  odc.addEdge(0, 3);\n  odc.queryConnected(1, 2);      // -> true (via 1-0-3-2)\n\n  const ans = odc.solve();\n  assert(\n    JSON.stringify(ans) === JSON.stringify([2, true, 1, 2, false, true]),\n    'Offline dynamic connectivity answers: ' + JSON.stringify(ans)\n  );\n\n  return { passed: 5, total: 5 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n\nif (require.main === module) {\n  const res = runTests();\n  console.log('All tests passed:', res);\n}\n\n",
