    "starterCode": "'use strict';\n\nclass DLXNode {\n  constructor(colHeader = null, rowId = -1) {\n    this.L = this;\n    this.R = this;\n    this.U = this;\n    this.D = this;\n    this.C = colHeader || this;\n    this.rowId = rowId;\n    this.size = 0; // used on column headers\n    this.colId = -1;\n  }\n}\n\nclass DancingLinksSolver {\n  constructor(numCols, rows = []) {\n    this.numCols = numCols;\n    this.header = new DLXNode();\n    this.columns = [];\n    this._initColumns(numCols);\n    for (let r = 0; r < rows.length; r++) {\n      this.addRow(r, rows[r]);\n    }\n  }\n\n  _initColumns(numCols) {\n    // TODO (Step 1): Create numCols column header nodes linked horizontally in a circular ring with this.header\n  }\n\n  addRow(rowId, colIndices) {\n    // TODO (Step 1): Insert a node into each specified column's vertical circular list and link them horizontally\n  }\n\n  cover(col) {\n    // TODO (Step 2): Unlink col header horizontally, and for each row in col, unlink all other nodes in that row vertically\n  }\n\n  uncover(col) {\n    // TODO (Step 2): In exact reverse order (U then L), relink each row's nodes vertically and relink col header horizontally\n  }\n\n  _chooseMinColumn() {\n    // TODO (Step 3): S-heuristic (MRV): return column header with minimum col.size\n    return null;\n  }\n\n  solveOne() {\n    // TODO (Step 4): Recursive Algorithm X search returning array of selected rowIds (or null if no exact cover)\n    return null;\n  }\n\n  solveAll(limit = 100) {\n    // TODO (Step 4): Enumerate up to `limit` exact cover solutions\n    return [];\n  }\n}\n\nmodule.exports = { DancingLinksSolver };\n",
    "solutionCode": "'use strict';\n\nclass DLXNode {\n  constructor(colHeader = null, rowId = -1) {\n    this.L = this;\n    this.R = this;\n    this.U = this;\n    this.D = this;\n    this.C = colHeader || this;\n    this.rowId = rowId;\n    this.size = 0;\n    this.colId = -1;\n  }\n}\n\nclass DancingLinksSolver {\n  constructor(numCols, rows = []) {\n    this.numCols = numCols;\n    this.header = new DLXNode();\n    this.columns = [];\n    this._initColumns(numCols);\n    for (let r = 0; r < rows.length; r++) {\n      this.addRow(r, rows[r]);\n    }\n  }\n\n  _initColumns(numCols) {\n    for (let c = 0; c < numCols; c++) {\n      const col = new DLXNode();\n      col.colId = c;\n      col.L = this.header.L;\n      col.R = this.header;\n      this.header.L.R = col;\n      this.header.L = col;\n      this.columns.push(col);\n    }\n  }\n\n  addRow(rowId, colIndices) {\n    if (!colIndices || colIndices.length === 0) return;\n    let first = null;\n    for (const cIdx of colIndices) {\n      const col = this.columns[cIdx];\n      const node = new DLXNode(col, rowId);\n      // Insert at bottom of column vertical circular list\n      node.U = col.U;\n      node.D = col;\n      col.U.D = node;\n      col.U = node;\n      col.size++;\n\n      if (first === null) {\n        first = node;\n      } else {\n        node.L = first.L;\n        node.R = first;\n        first.L.R = node;\n        first.L = node;\n      }\n    }\n  }\n\n  cover(col) {\n    col.R.L = col.L;\n    col.L.R = col.R;\n    for (let i = col.D; i !== col; i = i.D) {\n      for (let j = i.R; j !== i; j = j.R) {\n        j.D.U = j.U;\n        j.U.D = j.D;\n        j.C.size--;\n      }\n    }\n  }\n\n  uncover(col) {\n    for (let i = col.U; i !== col; i = i.U) {\n      for (let j = i.L; j !== i; j = j.L) {\n        j.C.size++;\n        j.D.U = j;\n        j.U.D = j;\n      }\n    }\n    col.R.L = col;\n    col.L.R = col;\n  }\n\n  _chooseMinColumn() {\n    let best = null;\n    let minSize = Infinity;\n    for (let c = this.header.R; c !== this.header; c = c.R) {\n      if (c.size < minSize) {\n        minSize = c.size;\n        best = c;\n        if (minSize === 0) break;\n      }\n    }\n    return best;\n  }\n\n  solveAll(limit = 100) {\n    const solutions = [];\n    const partial = [];\n\n    const search = () => {\n      if (solutions.length >= limit) return;\n      if (this.header.R === this.header) {\n        solutions.push([...partial]);\n        return;\n      }\n      const c = this._chooseMinColumn();\n      if (c.size === 0) return;\n      this.cover(c);\n      for (let r = c.D; r !== c; r = r.D) {\n        partial.push(r.rowId);\n        for (let j = r.R; j !== r; j = j.R) this.cover(j.C);\n        search();\n        for (let j = r.L; j !== r; j = j.L) this.uncover(j.C);\n        partial.pop();\n        if (solutions.length >= limit) break;\n      }\n      this.uncover(c);\n    };\n\n    search();\n    return solutions;\n  }\n\n  solveOne() {\n    const res = this.solveAll(1);\n    return res.length > 0 ? res[0] : null;\n  }\n}\n\nmodule.exports = { DancingLinksSolver };\n",
    "testHarness": "'use strict';\n\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  // Donald Knuth's classic 6-row, 7-column Exact Cover example from the Dancing Links paper:\n  // Row 0: {2, 4, 5}\n  // Row 1: {0, 3, 6}\n  // Row 2: {1, 2, 5}\n  // Row 3: {0, 3}\n  // Row 4: {1, 6}\n  // Row 5: {3, 4, 6}\n  // Unique exact cover: Rows {0, 3, 4} covering {2,4,5} U {0,3} U {1,6} = {0..6}\n  const rows = [\n    [2, 4, 5],\n    [0, 3, 6],\n    [1, 2, 5],\n    [0, 3],\n    [1, 6],\n    [3, 4, 6]\n  ];\n  const dlx = new DancingLinksSolver(7, rows);\n  const all = dlx.solveAll();\n  assert(all.length === 1, 'Knuth benchmark has exactly 1 solution');\n  const sol = [...all[0]].sort((a, b) => a - b);\n  assert(JSON.stringify(sol) === JSON.stringify([0, 3, 4]), 'Knuth solution is [0, 3, 4]');\n\n  // Verify toroidal pointers restored cleanly after search\n  let activeCols = 0;\n  for (let c = dlx.header.R; c !== dlx.header; c = c.R) activeCols++;\n  assert(activeCols === 7, 'All 7 columns restored intact after backtracking');\n\n  // Unsolvable exact cover instance\n  const unsolvable = new DancingLinksSolver(3, [[0, 1], [1, 2]]);\n  assert(unsolvable.solveOne() === null, 'Unsolvable instance returns null');\n\n  return { passed: 4, total: 4 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n",
