      "index.js": "'use strict';\n\nclass HirschbergDiff {\n  constructor({ matchCost = 0, subCost = 1, insCost = 1, delCost = 1 } = {}) {\n    this.matchCost = matchCost;\n    this.subCost = subCost;\n    this.insCost = insCost;\n    this.delCost = delCost;\n  }\n\n  _dpRow(a, b, reverse = false) {\n    const n = a.length, m = b.length;\n    let prev = new Int32Array(m + 1);\n    let curr = new Int32Array(m + 1);\n    for (let j = 0; j <= m; j++) prev[j] = j * this.insCost;\n\n    for (let i = 1; i <= n; i++) {\n      const ca = reverse ? a[n - i] : a[i - 1];\n      curr[0] = i * this.delCost;\n      for (let j = 1; j <= m; j++) {\n        const cb = reverse ? b[m - j] : b[j - 1];\n        const stepDiag = prev[j - 1] + (ca === cb ? this.matchCost : this.subCost);\n        const stepDel = prev[j] + this.delCost;\n        const stepIns = curr[j - 1] + this.insCost;\n        curr[j] = Math.min(stepDiag, stepDel, stepIns);\n      }\n      const tmp = prev; prev = curr; curr = tmp;\n    }\n    return prev;\n  }\n\n  _alignBase(a, b) {\n    const n = a.length, m = b.length;\n    const dp = Array.from({ length: n + 1 }, () => new Int32Array(m + 1));\n    for (let i = 0; i <= n; i++) dp[i][0] = i * this.delCost;\n    for (let j = 0; j <= m; j++) dp[0][j] = j * this.insCost;\n\n    for (let i = 1; i <= n; i++) {\n      for (let j = 1; j <= m; j++) {\n        const cost = a[i - 1] === b[j - 1] ? this.matchCost : this.subCost;\n        dp[i][j] = Math.min(\n          dp[i - 1][j - 1] + cost,\n          dp[i - 1][j] + this.delCost,\n          dp[i][j - 1] + this.insCost\n        );\n      }\n    }\n\n    const ops = [];\n    let i = n, j = m;\n    while (i > 0 || j > 0) {\n      if (i > 0 && j > 0) {\n        const isMatch = a[i - 1] === b[j - 1];\n        const cost = isMatch ? this.matchCost : this.subCost;\n        if (dp[i][j] === dp[i - 1][j - 1] + cost) {\n          ops.push({ op: isMatch ? 'MATCH' : 'SUB', aChar: a[i - 1], bChar: b[j - 1] });\n          i--; j--;\n          continue;\n        }\n      }\n      if (i > 0 && dp[i][j] === dp[i - 1][j] + this.delCost) {\n        ops.push({ op: 'DEL', aChar: a[i - 1], bChar: null });\n        i--;\n      } else {\n        ops.push({ op: 'INS', aChar: null, bChar: b[j - 1] });\n        j--;\n      }\n    }\n    ops.reverse();\n    return ops;\n  }\n\n  _hirschberg(a, b) {\n    const n = a.length, m = b.length;\n    if (n <= 1 || m <= 1) return this._alignBase(a, b);\n\n    const mid = n >> 1;\n    const aLeft = a.slice(0, mid);\n    const aRight = a.slice(mid);\n\n    const scoreL = this._dpRow(aLeft, b, false);\n    const scoreR = this._dpRow(aRight, b, true);\n\n    let bestK = 0;\n    let bestCost = Infinity;\n    for (let k = 0; k <= m; k++) {\n      const total = scoreL[k] + scoreR[m - k];\n      if (total < bestCost) {\n        bestCost = total;\n        bestK = k;\n      }\n    }\n\n    const leftOps = this._hirschberg(aLeft, b.slice(0, bestK));\n    const rightOps = this._hirschberg(aRight, b.slice(bestK));\n    return leftOps.concat(rightOps);\n  }\n\n  align(a, b) {\n    const operations = this._hirschberg(String(a), String(b));\n    let distance = 0;\n    for (const step of operations) {\n      if (step.op === 'MATCH') distance += this.matchCost;\n      else if (step.op === 'SUB') distance += this.subCost;\n      else if (step.op === 'INS') distance += this.insCost;\n      else if (step.op === 'DEL') distance += this.delCost;\n    }\n    return { distance, operations };\n  }\n}\n\nmodule.exports = { HirschbergDiff };\n",
      "test.js": "'use strict';\n\nconst exported = require('./index.js');\nObject.assign(globalThis, exported);\n\n'use strict';\n\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  const diff = new HirschbergDiff();\n\n  const verifyPair = (a, b, expectedDist) => {\n    const { distance, operations } = diff.align(a, b);\n    assert(distance === expectedDist, `distance(${a}, ${b}) expected ${expectedDist}, got ${distance}`);\n    // Reconstruct both strings from edit transcript\n    const recA = operations.filter(o => o.aChar !== null).map(o => o.aChar).join('');\n    const recB = operations.filter(o => o.bChar !== null).map(o => o.bChar).join('');\n    assert(recA === a, 'reconstructed A matches original');\n    assert(recB === b, 'reconstructed B matches original');\n  };\n\n  verifyPair('kitten', 'sitting', 3);\n  verifyPair('intention', 'execution', 5);\n  verifyPair('AGTACGCA', 'TATGC', 4);\n  verifyPair('', 'abcde', 5);\n  verifyPair('abcde', '', 5);\n\n  return { passed: 5, total: 5 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n\nif (require.main === module) {\n  const res = runTests();\n  console.log('All tests passed:', res);\n}\n\n",
